CREATE OR REPLACE FUNCTION p2713382g85093gg2(
    num1 numeric,
    num2 numeric
) RETURNS p2713382g85093gg11 AS $$
DECLARE
    result p2713382g85093gg11;
    product numeric;
    safe_prod bigint;
BEGIN
    result.value1 := num1;
    result.value2 := num2;

    -- Calculate product with overflow checking
    IF PGTYPESnumeric_mul(num1, num2, product) = -1 THEN
        IF errno = PGTYPES_NUM_OVERFLOW THEN
            RAISE EXCEPTION 'Product overflow in composite creation';
        END IF;
    END IF;

    -- Convert to long with overflow checking
    IF PGTYPESnumeric_to_long(product, safe_prod) = -1 THEN
        IF errno = PGTYPES_NUM_OVERFLOW THEN
            result.safe_product := NULL;
        ELSE
            result.safe_product := safe_prod;
        END IF;
    ELSE
        result.safe_product := safe_prod;
    END IF;

    RETURN result;
